239:
SELECT COUNT(DISTINCT c."bond_id") AS connection_count
FROM "connected" c
WHERE c."atom_id" LIKE 'TR%\_19' ESCAPE '\';

699:
SELECT u."creationdate"
FROM "users" AS u
WHERE u."displayname" = 'IrishStat';

714:
SELECT c."id", c."text", c."userdisplayname"
FROM "comments" c
WHERE c."userdisplayname" = 'Harvey Motulsky';

661:
SELECT "u"."age"
FROM "users" AS "u"
WHERE "u"."reputation" = (
    SELECT MAX("reputation") FROM "users"
)
LIMIT 1;

621:
SELECT DISTINCT b."name"
FROM "badges" b
JOIN "users" u ON b."userid" = u."id"
WHERE u."reputation" = (
    SELECT MIN("reputation") FROM "users"
);

588:
SELECT COUNT(*) AS total_comments
FROM "comments" c
WHERE c."userid" = 13;

572:
SELECT "viewcount"
FROM "posts"
WHERE "title" = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

745:
SELECT p."id"
FROM "publisher" AS p
WHERE p."publisher_name" = 'Star Trek';

803:
SELECT sp."id"
FROM "superpower" AS sp
WHERE LOWER(sp."power_name") = 'cryokinesis';

747:
SELECT COUNT(*) AS total_superheroes_without_full_name
FROM "superhero" AS s
WHERE s."full_name" IS NULL;

1377:
SELECT COUNT(DISTINCT "member_id") AS student_count
FROM "member"
WHERE LOWER(TRIM("position")) = 'president';

1365:
SELECT e."expense_description"
FROM "expense" e
JOIN "budget" b ON e."link_to_budget" = b."budget_id"
WHERE b."remaining" = (
    SELECT MIN("remaining") FROM "budget"
);
